import * as React from 'react';
import PropTypes from 'prop-types';
import Button from '@mui/material/Button';
import { styled } from '@mui/material/styles';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Divider, Grid } from '@mui/material';
import AdapterDateFns from '@mui/lab/AdapterDateFns';
import LocalizationProvider from '@mui/lab/LocalizationProvider';
import StaticDateRangePicker from '@mui/lab/StaticDateRangePicker';
const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

const BootstrapDialogTitle = (props) => {
  const { children, onClose, ...other } = props;
  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
};

BootstrapDialogTitle.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
};

export default function DateDialog({ open, setOpen, selectedDates, setSelectedDates, type, setType, monthDate, setMonthDate, flexibleType, setFlexibleType }) {
  const calender = 'Calender'
  const flexible = 'Flexible'
  const weekend = 'Weekend'
  const week = 'Week'
  const month = 'Month'
  const months = ["January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December"];
  const style1 = {
    borderRadius: '26px',
    boxSizing: 'border-box',
    padding: '10px 14px 9px',
    fontFamily: 'Inter',
    margin: '1px',
    fontSize: '14px',
    color: '#fff',
    backgroundColor: '#75969f',
    textTransform: 'none',
    '&:hover': {
      backgroundColor: '#75969f'
    }
  }
  const style2 = {
    borderRadius: '26px',
    boxSizing: 'border-box',
    padding: '10px 14px 9px',
    fontFamily: 'Inter',
    margin: '1px',
    fontSize: '14px',
    textTransform: 'none',
    color: '#000',
    backgroundColor: '#fff',
    '&:hover': {
      backgroundColor: '#fff'
    }
  }
  const styleMonth1 = {
    borderRadius: '26px',
    boxSizing: 'border-box',
    padding: '10px 14px 9px',
    border: '1px solid rgba(0, 0, 0, 0.05)',
    fontFamily: 'Inter',
    margin: '1px',
    fontSize: '14px',
    textTransform: 'none',
    color:'#000'
  }
  const styleMonth2 = {
    borderRadius: '26px',
    boxSizing: 'border-box',
    padding: '10px 14px 9px',
    fontFamily: 'Inter',
    border: '3px solid #75969f',
    margin: '5px',
    fontSize: '14px',
    textTransform: 'none',
    color:'#000'
  }
  const handleClickOpen = () => {
    setOpen(true);
  };
  const handleClose = () => {
    setOpen(false);
  };

  const handleChangeType = (event) => {
    setType(event.target.name)
  }
  const handleChangeFlexibleType = (event) => {
    setFlexibleType(event.target.name)
  }
  const handleChangeMonth = (event) => {
    setMonthDate(event.target.name)
  }
  const clearDates = () => { 
    setSelectedDates([null, null]) 
    setMonthDate('February')
    setFlexibleType(weekend)
  }
  return (
    <BootstrapDialog
      maxWidth="sm"
      onClose={handleClose}
      aria-labelledby="customized-dialog-title"
      open={open}
    >
      <BootstrapDialogTitle id="customized-dialog-title" align="center" onClose={handleClose}>
        <Box sx={{
          width: '30%',
          border: '1px solid rgba(0, 0, 0, 0.05)',
          borderRadius: '26px',
          boxSizing: 'border-box',
          padding: '2px',
          marginLeft: '35%'
        }}>
          <Grid container>
            <Grid item xs={6}>
              <Button onClick={handleChangeType} name={calender} sx={{ ...type === calender ? style1 : style2, marginRight: '0px' }}>
                {calender}
              </Button>
            </Grid>
            <Grid item xs={6}>
              <Button onClick={handleChangeType} name={flexible} sx={{ ...type === flexible ? style1 : style2, marginLeft: '0px' }}>
                {flexible}
              </Button>
            </Grid>
          </Grid>
        </Box>
      </BootstrapDialogTitle>
      <DialogContent>
        {type === calender ?
          <Box>
            <LocalizationProvider dateAdapter={AdapterDateFns}>
              <StaticDateRangePicker
                displayStaticWrapperAs="desktop"
                minDate={new Date()}
                views={['day']}
                value={selectedDates}
                InputProps={{
                  disableUnderline: true
                }}
                onChange={(newValue) => {
                  setSelectedDates(newValue);
                }}
              />
            </LocalizationProvider>
          </Box> :
          <Box>
            <Divider />
            <Box sx={{margin:'35px 0 10px', display:"flex" ,alignItems:'center', justifyContent:"center", direction:"column"}}>
              Stay for a &nbsp;<b>{flexibleType}</b>
              </Box>
            <Box sx={{
              width: '100%',
              border: '1px solid rgba(0, 0, 0, 0.05)',
              borderRadius: '26px',
              boxSizing: 'border-box',
              padding: '2px',
            }}>
              <Grid container spacing={2}>
                <Grid item xs={4}>
                  <Button onClick={handleChangeFlexibleType} name={weekend} sx={{ ...flexibleType === weekend ? style1 : style2, marginRight: '0px' }}>
                    {weekend}
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button onClick={handleChangeFlexibleType} name={week} sx={{ ...flexibleType === week ? style1 : style2, marginLeft: '0px' }}>
                    {week}
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button onClick={handleChangeFlexibleType} name={month} sx={{ ...flexibleType === month ? style1 : style2, marginLeft: '0px' }}>
                    {month}
                  </Button>
                </Grid>
              </Grid>
            </Box>
            <Box sx={{margin:'35px 0 10px', display:"flex" ,alignItems:'center', justifyContent:"center", direction:"column"}}>
            Go in&nbsp; <b>{monthDate}</b>
            </Box>
            <Box>
              <Divider>2022</Divider>
            <Box sx={{marginBottom:'20px',marginTop:'20px', display:"flex" ,alignItems:'center', justifyContent:"center", direction:"column"}}>
              <Grid container>
              {months.splice(1).map(item => (
                  <Grid item xs={6} sm={4} md={2} lg={2}>
                  <Button onClick={handleChangeMonth} name={item} sx={{ ...monthDate === item  ? styleMonth2 : styleMonth1 }}>
                  {item}
                  </Button>
                  </Grid>
              ))}
              </Grid>
              </Box>
              <Divider>2023</Divider>
              <Box sx={{marginTop:'20px', marginBottom:'20px',display:"flex" ,alignItems:'center', justifyContent:"center", direction:"column"}}>

              {months.splice(0, 1).map(item => (
                <Button onClick={handleChangeMonth} name={item} sx={{ ...monthDate === item  ? styleMonth2 : styleMonth1 }}>
                {item}
                </Button>
              ))}
              </Box>
            </Box>
          </Box>
        }
        <Divider />
      </DialogContent>
      <DialogActions>
        <Button autoFocus onClick={clearDates} sx={{
          textTransform: 'none',
          color: '#000',
          fontSize: '15px',
          fontFamily: 'Inter',
          marginLeft: '10px',
          borderRadius: '12px',
          flex: '1 0 0',
          justifyContent: "flex-start",
          fontWeight: '500'
        }}
        >
          Clear
        </Button>
        <Button autoFocus onClick={handleClose} sx={{
          textTransform: 'none',
          color: '#fff',
          backgroundColor: '#75969f',
          fontFamily: 'Gilory',
          fontSize: '17px',
          marginLeft: '20px',
          padding: '6px 20px',
          borderRadius: '12px',
          '&:hover': {
            backgroundColor: '#75969f'
          }
        }}>
          Apply dates
        </Button>
      </DialogActions>
    </BootstrapDialog>
  );
}
