import { Box } from '@mui/material';
import React, { useState } from 'react';
import { useEffect } from 'react';
//import Navbar from "./components/navbar/navbar";

export default function HomeImages() {
    const [imageIndex, setImageIndex] = useState(0)
    const [imagesList, setImagesList] = useState([])
    const importAll = (r) => {
        return r.keys().map(r);
    }
    let timer

    const updateIndex = () => {
        timer = !timer && setInterval(() => {
            setImageIndex(prevCount => prevCount + 1)
        }, 5000)
    }
    useEffect(() => {
        setImagesList(importAll(require.context('./media/', false, /\.(png|jpe?g|svg)$/)))
        updateIndex()
        return () => clearInterval(timer);
    }, [])
    return (
        <div>
            {imagesList.length !== 0 ?
                <Box sx={{ 
                    top: "0", 
                    height:'450px', 
                    left: "0", 
                    right: "0",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    backgroundImage: `url(${imagesList[imageIndex % imagesList.length]})`,
                }} >
                    <Box sx={{
                        fontFamily: 'Gilory',
                        fontWeight: 'bold',
                        fontSize: '72px',
                        lineHeight: '94.47%',
                        textAlign: 'center',
                        color: '#FFF',
                        margin: '10px',
                        textShadow: '0px 1px 2px rgba(0, 0, 0, 0.3), 0px 40px 80px rgba(0, 0, 0, 0.3)'
                    }}>
                        <div>Escape</div>
                        <div>the ordinary</div>
                    </Box>
                    <Box sx={{
                        fontFamily: 'Gilory',
                        fontWeight: 'bold',
                        lineHeight: '94.47%',
                        fontSize: '18px',
                        textAlign: 'center',
                        color: '#FFF',
                        textShadow: '0px 1px 2px rgba(0, 0, 0, 0.3), 0px 40px 80px rgba(0, 0, 0, 0.3)'
                    }}>
                        <div>A new way to stay in your favorite neighbourhoods</div>
                        <div>around the world.</div>
                    </Box>
                </Box>
                :
                <div></div>
            }
        </div>
    );
}

