import * as React from 'react';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import Menu from '@mui/material/Menu';
import MenuIcon from '@mui/icons-material/Menu';
import Container from '@mui/material/Container';
import Avatar from '@mui/material/Avatar';
import Button from '@mui/material/Button';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import Tooltip from '@mui/material/Tooltip';
import MenuItem from '@mui/material/MenuItem';
import { Grid } from '@mui/material';
import { Link } from 'react-scroll'
const settings = ['Profile', 'Account', 'Dashboard', 'Logout'];

export default function Navbar() {
  const [anchorElNav, setAnchorElNav] = React.useState(null);
  const [anchorElUser, setAnchorElUser] = React.useState(null);
  const [backgroundColor, setBackgroundColor] = React.useState('transparent');

  //navbar scroll changeBackground function
  const changeBackground = () => {
    if (window.scrollY <= 176) {
      setBackgroundColor('transparent')
    } else {
      setBackgroundColor('#fff')
    }
  }

  React.useEffect(() => {
    changeBackground()
    // adding the event when scroll change background
    window.addEventListener("scroll", changeBackground)
  })
  const handleOpenNavMenu = (event) => {
    setAnchorElNav(event.currentTarget);
  };
  const handleOpenUserMenu = (event) => {
    setAnchorElUser(event.currentTarget);
  };

  const handleCloseNavMenu = () => {
    setAnchorElNav(null);
  };

  const handleCloseUserMenu = () => {
    setAnchorElUser(null);
  };

  return (
    <AppBar position="fixed" sx={{ backgroundColor: backgroundColor, boxShadow: 'none', height: '67px' }}>
      <Container maxWidth="xl">
        <Toolbar disableGutters>
          <Typography
            variant="h6"
            noWrap
            component="div"
            sx={{
              mr: 2, flexGrow: 1
              // ,display: { xs: 'none', md: 'flex' } 
            }}
          >
            {
              backgroundColor === 'transparent' ?
                <Box>
                  <a href='/' style={{
                    textDecoration: "none",
                    color: 'inherit'
                  }}>
                    <Box>
                      <img width='69.58 px' height='14.15 px' src="./logo1.png" alt="logo" />
                    </Box>
                    <Box>
                      <img width='96.05 px' height='22.5 px' src="./logo2.png" alt="logo" />
                    </Box>
                  </a>
                </Box>
                :
                <Box>
                  <a href='/' style={{
                    textDecoration: "none",
                    color: 'inherit'
                  }}>

                    <img width='96.05 px' height='22.5 px' src="./logo3.svg" alt="logo" />
                  </a>
                </Box>
            }
          </Typography>

          <Box sx={{ flexGrow: 0, display: { xs: 'flex', sm: 'none' }, color: backgroundColor === 'transparent' ? 'white' : 'black' }}>
            <IconButton
              size="large"
              aria-label="account of current user"
              aria-controls="menu-appbar"
              aria-haspopup="true"
              onClick={handleOpenNavMenu}
              color="inherit"
            >
              <MenuIcon />
            </IconButton>
            <Menu
              id="menu-appbar"
              anchorEl={anchorElNav}
              anchorOrigin={{
                vertical: 'bottom',
                horizontal: 'left',
              }}
              keepMounted
              transformOrigin={{
                vertical: 'top',
                horizontal: 'left',
              }}
              open={Boolean(anchorElNav)}
              onClose={handleCloseNavMenu}
              sx={{
                display: { xs: 'block', sm: 'none' }
              }}
            >
              <MenuItem key='Help Center' onClick={handleCloseNavMenu}>
                <Typography textAlign="center">Help Center</Typography>
              </MenuItem>
              <MenuItem key='Contact' onClick={handleCloseNavMenu}>
                <Typography textAlign="center"><ul style={{ listStyle: 'none', paddingLeft: '0px' }}><li><Link activeClass="active" to="contact" spy={true} smooth={true}>Contact</Link></li></ul></Typography>
              </MenuItem>
            </Menu>
          </Box>

          <Box sx={{ flexGrow: 0, display: { xs: 'none', sm: 'flex' } }}>
            <Button
              key='Help Center'
              onClick={handleCloseNavMenu}
              sx={{ my: 2, height: '38px', display: 'block', border: '1px solid', borderRadius: '40px', boxSizing: 'border-box', color: backgroundColor === 'transparent' ? 'white' : 'black', borderColor: backgroundColor === 'transparent' ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.2)' }}
            >
              Help Center
            </Button>
            <Button
              key='Contact'
              onClick={handleCloseNavMenu}
              sx={{ my: 2, display: 'block', height: '38px', color: backgroundColor === 'transparent' ? 'white' : 'black', borderColor: backgroundColor === 'transparent' ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.2)' }}
            >
              <ul style={{ listStyle: 'none', paddingLeft: '0px', margin: '0px' }}><li><Link activeClass="active" to="contact" spy={true} smooth={true}>Contact</Link></li></ul>
            </Button>
          </Box>
          <hr style={{
            border: '1px solid rgba(255, 255, 255, 0.3)',
            transform: 'rotate(90deg)',
            width: '12px',
            height: '0.2px',
          }}>
          </hr>
          <Box sx={{ flexGrow: 0 }}>


            <Tooltip title="Open settings">
              <IconButton onClick={handleOpenUserMenu} sx={{ p: 0 }}>
                <Avatar alt="Remy Sharp" src="/static/images/avatar/2.jpg" />
              </IconButton>
            </Tooltip>
            <IconButton
              size="large"
              aria-label="account of current user"
              aria-controls="menu-appbar"
              aria-haspopup="true"
              onClick={handleOpenNavMenu}
              color="inherit"
            >
              <KeyboardArrowDownIcon />
            </IconButton>
            <Menu
              sx={{ mt: '45px' }}
              id="menu-appbar"
              anchorEl={anchorElUser}
              anchorOrigin={{
                vertical: 'top',
                horizontal: 'right',
              }}
              keepMounted
              transformOrigin={{
                vertical: 'top',
                horizontal: 'right',
              }}
              open={Boolean(anchorElUser)}
              onClose={handleCloseUserMenu}
            >
              {settings.map((setting) => (
                <MenuItem key={setting} onClick={handleCloseUserMenu}>
                  <Typography textAlign="center">{setting}</Typography>
                </MenuItem>
              ))}
            </Menu>
          </Box>
        </Toolbar>
      </Container>
    </AppBar>
  );
};
