import * as React from 'react';
import Box from '@mui/material/Box';
import { Button, Divider, FormControl, Grid, IconButton, InputLabel, Menu, MenuItem, Select, TextField } from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
import SearchIcon from '@mui/icons-material/Search';
import DateDialog from './dateDialog';
const getPointTop = () => {
    const width = window.innerWidth;
    if (width > 899) return '418px'
    return '340px'
}
export default function SearchForm() {
    const cities = ['Dubai', 'Montreal', 'Manama']
    const [pointTop, setPointTop] = React.useState(getPointTop());
    const [datesDilog, setDatesDilog] = React.useState(false);
    const [citiesMenu, setCitiesMenu] = React.useState(null);
    const [type, setType] = React.useState('Calender');
    const [monthDate, setMonthDate] = React.useState('February');
    const [flexibleType, setFlexibleType] = React.useState('Weekend');
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ];
    const [selectedDates, setSelectedDates] = React.useState([null, null]);
    const [searchForm, setSearchForm] = React.useState({
        city: '',
        dates: '',
        guestsCount: 0
    })

    React.useEffect(() => {
        function handleResize() {
            setPointTop(getPointTop());
        }
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);
    const handleChange = (e) => {
        setSearchForm({ ...searchForm, [e.target.name]: e.target.value });
    };
    const changeGuestCounter = (num) => {
        setSearchForm({ ...searchForm, guestsCount: searchForm.guestsCount + num });
    };
    const addGuest = (e) => {
        changeGuestCounter(1)
    };
    const removeGuest = (e) => {
        changeGuestCounter(-1)
    };


    const openDatesDilog = (event) => {
        setDatesDilog(event.currentTarget);
    };

    return (
        <Box position='absolute' sx={{
            width: '100%',
            top: pointTop,
            // top: '0px',
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            // marginTop:'32%'
        }}>
            <DateDialog
                open={datesDilog}
                setOpen={setDatesDilog}
                selectedDates={selectedDates}
                setSelectedDates={setSelectedDates}
                type={type}
                setType={setType}
                monthDate={monthDate}
                setMonthDate={setMonthDate}
                flexibleType={flexibleType}
                setFlexibleType={setFlexibleType}
            />
            <Box sx={{
                fontFamily: 'Gilory',
                width: '80%',
                lineHeight: '94.47%',
                display: 'flex',
                boxSizing: 'border-box',
                borderRadius: '20px',
                backdropFilter: 'blur(40px)',
            }}>
                <Grid container
                    alignItems="center"
                    justifyContent="center"
                    spacing="7px"
                    padding="6px 6px 6px 12px"
                >
                    <Grid item xs={12} sm={12} md={3}>
                        <Grid container
                            alignItems="center"
                            justifyContent="center">
                            <Grid item xs={12} sm={12} md={11}>
                                <FormControl variant="standard" fullWidth
                                    sx={{
                                        padding: "0px 0 12px 11px"
                                    }}
                                >
                                    <InputLabel id="demo-simple-select-standard-label" sx={{
                                        padding: "0px 0 12px 11px"
                                    }}>Select a city</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-standard-label"
                                        id="city"
                                        name="city"
                                        value={searchForm.city}
                                        onChange={handleChange}
                                        IconComponent={null}
                                        label="CITY"
                                    >
                                        {cities.map(city => <MenuItem value={city}>{city}</MenuItem>)}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={0} sm={0} md={1} sx={{ display: { xs: 'none', sam: 'none', md: 'flex' } }}>
                                <Divider orientation="vertical" variant="middle" sx={{ height: '16px' }} flexItem />
                            </Grid>
                        </Grid>
                    </Grid>
                    <Grid item xs={12} sm={12} md={3}>
                        <Grid container
                            alignItems="center"
                            justifyContent="center">
                            <Grid item xs={12} sm={12} md={11}>
                                <Box sx={{
                                    fontFamily: 'Inter',
                                    fontStyle: 'normal',
                                    fontWeight: '500',
                                    fontSize: '12px',
                                    lineHeight: '93.47%',
                                    letterSpacing: '0.04em',
                                    textTransform: 'uppercase',
                                    color: '#67767C',
                                    padding: "0px 0 12px 11px"
                                }}>
                                    Dates
                                </Box>
                                <Button
                                    fullWidth sx={{
                                        justifyContent: "flex-start",
                                        padding: "0px 0 12px 11px",
                                        '&:hover': {
                                            borderBottom: "2px solid #333"
                                        }
                                    }} onClick={openDatesDilog}>
                                    {!((type==='Calender'&&selectedDates[0] !== null && selectedDates[1] !== null) || type==='Flexible') ?
                                        <Box sx={{
                                            fontFamily: 'Gilroy',
                                            fontStyle: 'normal',
                                            fontWeight: 'normal',
                                            fontSize: '19px',
                                            lineHeight: '93.47%',
                                            color: '#858585',
                                            textTransform: 'none'
                                        }}>
                                            Select a dates
                                        </Box>
                                        :
                                        <Box sx={{
                                            fontFamily: 'Gilroy',
                                            fontStyle: 'normal',
                                            fontWeight: 'normal',
                                            fontSize: '19px',
                                            lineHeight: '93.47%',
                                            color: '#000',
                                            textTransform: 'none'
                                        }}>
                                            {
                                                type==='Calender'?
                                                <Box>
{selectedDates[0].getDate()} {monthNames[selectedDates[0].getMonth()]} - {selectedDates[1].getDate()} {monthNames[selectedDates[1].getMonth()]}
                                                </Box>:
                                                <Box>
                                                    {flexibleType} in {monthDate}
                                                </Box>
                                            }
                                        </Box>}
                                </Button>
                            </Grid>
                            <Grid item xs={0} sm={0} md={1} sx={{ display: { xs: 'none', sam: 'none', md: 'flex' } }}>
                                <Divider orientation="vertical" variant="middle" sx={{ height: '16px' }} flexItem />
                            </Grid>
                        </Grid>
                    </Grid>
                    <Grid item xs={12} sm={12} md={3}>
                        <Grid container>
                            <Grid item xs={6}>
                                <FormControl variant="standard"
                                    sx={{
                                        padding: "0px 0 12px 11px"
                                    }}
                                >
                                    <Box sx={{
                                        fontSize: '12px',
                                        textTransform: 'uppercase',
                                        color: '#67767C'
                                    }}>
                                        Guests
                                    </Box>
                                    <Box>
                                        {searchForm.guestsCount === 0 ?
                                            <Box sx={{
                                                color: '#858585',
                                                fontSize: '18px',
                                                marginTop: '10px'
                                            }}>
                                                Add guest
                                            </Box> :
                                            <Box sx={{
                                                color: '#000',
                                                fontSize: '19px',
                                                marginTop: '10px'
                                            }}>
                                                {searchForm.guestsCount} guest
                                            </Box>}
                                    </Box>
                                </FormControl>
                            </Grid>
                            <Grid item xs={6} align="right">
                                <Box sx={{
                                    width: '70px',
                                    height: '40px',
                                    border: '1px solid rgba(0, 0, 0, 0.05)',
                                    borderRadius: '26px',
                                    boxSizing: 'border-box',
                                    padding: '2px',
                                    display: 'flex',
                                    margin: '10px 0 12px 11px'
                                }}>
                                    <IconButton
                                        color="primary"
                                        aria-label="upload picture"
                                        component="span"
                                        disabled={!searchForm.guestsCount || searchForm.guestsCount === 1}
                                        onClick={removeGuest}
                                        size="small"
                                        style={{ color: (!searchForm.guestsCount || searchForm.guestsCount === 1) ? '##00000033' : '#000' }}
                                    >
                                        <RemoveIcon fontSize="small" />
                                    </IconButton>
                                    <IconButton
                                        aria-label="upload picture"
                                        component="span"
                                        onClick={addGuest}
                                        size="small"
                                        style={{ color: '#000' }}
                                    >
                                        <AddIcon fontSize="small" />
                                    </IconButton>
                                </Box>
                            </Grid>
                        </Grid>
                    </Grid>
                    <Grid item xs={12} sm={12} md={3}>
                        <Button
                            sx={{
                                background: 'linear-gradient(90deg, #72A2AF 0%, #4A7889 100%)',
                                borderRadius: '20px',
                                width: '100%',
                                height: '60px',
                                color: 'white',
                                fontFamily: 'Gilroy',
                                fontStyle: 'normal',
                                fontWeight: '600',
                                fontSize: '20px',
                                lineHeight: '93.47%',
                                textTransform: 'none'
                            }}
                        >
                            <SearchIcon />
                            Search
                        </Button>
                    </Grid>
                </Grid>
            </Box>
        </Box >
    );
};
